package com.rpb.reservation.workforce;
import com.rpb.reservation.workforce.api.WorkforceStatutoryPolicyController;import com.rpb.reservation.workforce.statutory.StatutoryPolicyService;import com.rpb.reservation.walkin.api.*;import com.rpb.reservation.walkin.auth.LocalRuntimeSecurityConfiguration;import java.util.*;import org.junit.jupiter.api.Test;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.autoconfigure.web.servlet.WebMvcTest;import org.springframework.boot.test.mock.mockito.MockBean;import org.springframework.context.annotation.Import;import org.springframework.test.context.ActiveProfiles;import org.springframework.test.context.TestPropertySource;import org.springframework.test.web.servlet.MockMvc;import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;import static org.mockito.Mockito.*;import static org.mockito.ArgumentMatchers.*;
@WebMvcTest(WorkforceStatutoryPolicyController.class) @Import({LocalRuntimeSecurityConfiguration.class,com.rpb.reservation.appgate.api.AppGateApiErrorMapper.class}) @ActiveProfiles("local") @TestPropertySource(properties="rpb.local-auth.enabled=true")
class WorkforceStatutoryPolicyApiTest {
 @Autowired MockMvc mvc;@MockBean CurrentActorProvider actors;@MockBean StatutoryPolicyService templates;@MockBean com.rpb.reservation.appgate.application.AppGateService gate;@MockBean com.rpb.reservation.appgate.application.AppGateDenialAuditService denialAudit;
 String base="/api/v1/stores/"+UUID.randomUUID()+"/workforce/statutory-policies";
 @Test void readsNeedActorAndWritesKeepSameOriginAndNarrowSecurity()throws Exception{mvc.perform(get(base)).andExpect(status().isUnauthorized()).andExpect(header().string("Cache-Control","private, no-store"));mvc.perform(put(base+"/"+UUID.randomUUID()).contentType("application/json").content("{}")).andExpect(status().isForbidden());mvc.perform(put(base+"/"+UUID.randomUUID()).header("X-RPB-Workforce","1").header("Sec-Fetch-Site","cross-site").contentType("application/json").content("{}")).andExpect(status().isForbidden());mvc.perform(delete(base+"/"+UUID.randomUUID())).andExpect(status().isForbidden());verifyNoInteractions(templates);}
 @Test void authenticatedProtectedPathUsesServiceAndPrivateResponses()throws Exception{when(actors.currentActor()).thenReturn(Optional.of(new CurrentActor(UUID.randomUUID(),UUID.randomUUID(),"staff",Set.of(),Set.of(),Set.of())));when(templates.list(any(),any())).thenReturn(new com.rpb.reservation.workforce.statutory.StatutoryPolicies.Page(List.of(),true));mvc.perform(get(base)).andExpect(status().isOk()).andExpect(jsonPath("$.items").isArray()).andExpect(header().string("Cache-Control","private, no-store"));mvc.perform(put(base+"/"+UUID.randomUUID()).header("X-RPB-Workforce","1").contentType("application/json").content("{}")).andExpect(status().isOk());verify(templates).save(any(),any(),any(),any());}
}
